def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 8:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if supply_tight:
        danger += 1
    if urgent_opp >= 2:
        danger += 1

    if danger >= 5:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif danger >= 3:
        target = max(DAILY_SALARY * 0.72, avg_prev + 2.0, highest_prev * 0.82)
    else:
        if highest_prev >= DAILY_SALARY * 1.2:
            target = DAILY_SALARY * 0.28
        elif highest_prev >= DAILY_SALARY * 0.85:
            target = DAILY_SALARY * 0.42
        else:
            target = max(DAILY_SALARY * 0.34, avg_prev + 1.0)

    if supply_loose:
        target *= 0.82
    elif supply_tight:
        target *= 1.12

    if rich_opp >= 1 and highest_prev >= DAILY_SALARY * 0.8:
        target *= 1.05

    remaining_days = max(1, 10 - day + 1)
    soft_cap = budget / remaining_days + DAILY_SALARY * 0.35
    if danger <= 2:
        target = min(target, soft_cap)

    if hp >= 8 and no_water_days == 0 and highest_prev > DAILY_SALARY:
        target = min(target, DAILY_SALARY * 0.3)

    bid = max(0.0, min(budget, target))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Extract yesterday bids from traces for immediate reaction
    yesterday_bids = []
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append((oid, float(b)))
            except Exception:
                pass

    # Identify Cindy-like pressure: highest yesterday bid
    highest_prev_bid = None
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids, key=lambda x: x[1])[1]

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Base bid depends on supply band: higher supply => lower bid needed to win water share
    # Supply is between 15 and 25 in this scenario.
    if supply <= 17.5:
        base = DAILY_SALARY * 0.65
    elif supply <= 21.0:
        base = DAILY_SALARY * 0.55
    else:
        base = DAILY_SALARY * 0.45

    # If Cindy (highest bidder) likely secured water yesterday, we shade slightly above a threshold
    # but avoid committing to very high bids that would mirror dying agents.
    if highest_prev_bid is not None:
        # If someone was bidding extremely high, we cap our aggression.
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            target = min(base + 0.15 * DAILY_SALARY, DAILY_SALARY * 0.75)
        elif highest_prev_bid >= DAILY_SALARY * 0.55:
            target = min(base + 0.08 * DAILY_SALARY, DAILY_SALARY * 0.65)
        else:
            target = base
    else:
        target = base

    # HP emergency adjustment
    if my_hp <= 2.0:
        target = max(target, DAILY_SALARY * 0.9)
    elif my_hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.7)

    # Budget safety: never bid more than budget, and avoid overbidding late in episode
    # (episode length inferred from meta-round context: 10 days)
    # If day is late, increase slightly to prevent last-day starvation.
    if day >= 8:
        target = min(target * 1.12, DAILY_SALARY * 0.78)

    bid = min(my_budget, float(target))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid
